#pragma once
// Where each Blockbench block texture (/axeolon/block/<name>.png) sits in the terrain atlas
// (rows 512..1023 of the 256x1024 terrain.rgba). Generated by tools/gen_assets.py.
struct RigTexture {
    const char* name;
    int x, y, w, h; // texels, y from the top of the atlas
};
extern const RigTexture RIG_TEXTURES[];
extern const int RIG_TEXTURE_COUNT;
